  const handleMasterNameChange1 = (value) => {
    setRatedListChargeId1(0);
    setTestTypeId1(0);
    setSearchChargeWardList1(newChargeWardList1);
    if (RATELISTCHARGETYPE2 !== "OPD" && searchChargeWardList1.length > 0) {
      document.getElementById("selectAllWarsCheck").checked = false;
    }
    setRatedListChargeName1(value);
    var chargesList = [];
    var chargeNameData = [...mainChargeNameList1];
    for (const j in chargeNameData) {
      if (chargeNameData[j].chargeTypeId === CHARGETYPEID2) {
        chargesList.push(chargeNameData[j]);
      }
    }
    if (value !== "") {
      // Filter the list based on the condition
      var filteredChargeNameList = chargesList.filter((charge) =>
        charge.chargeMasterName.toUpperCase().includes(value.toUpperCase())
      );
      setChargeNameList1(filteredChargeNameList);
    } else {
      var newChargeNameList = [];
      var chargeNameData = [...mainChargeNameList1];
      for (const j in chargeNameData) {
        if (chargeNameData[j].chargeTypeId === CHARGETYPEID2) {
          var filternameList = chargeNameData[j];
          newChargeNameList.push(filternameList);
        }
      }
      setChargeNameList1(newChargeNameList);
    }
    if (value !== null && RATELISTCHARGETYPE2 === "INVESTIGATION") {
      var chargeNameLists = [...chargeNameList1];
      if (chargeNameLists.length === 0) {
        getInvChargeList(value);
      } else {
        for (const item of chargeNameLists) {
          if (!item.chargeMasterName.includes(value.toUpperCase())) {
            getInvChargeList(value);
            break;
          }
        }
      }
    }
  };

  const getWardListPrevCharges = (chrTypeId, masterID, pracID) => {
    if (searchChargeWardList.length > 0) {
      if (document.getElementById("selectAllWarsCheck")) {
        document.getElementById("selectAllWarsCheck").checked = false;
      }
    }
    var isProcedureChk = false;
    var consulatantID;
    if (isProcedureChk) {
      consulatantID = pracID ? pracID : 0;
    } else {
      consulatantID = 0;
    }
    var clinicid = localStorage.getItem("ClinicId");

    var userID = localStorage.getItem("UserId");
    var branchID = localStorage.getItem("branch_id");

    var myHeaders = apiHeaders(0);

    var raw = JSON.stringify({
      chargeTypeId: chrTypeId,
      practitionerId: pracID ? pracID : 0,
      testTypeId: 0,
      thirdPartyId: 0,
      wardId: null,
      name: null,
      chargeMasterId: masterID ? masterID : 0,
    });

    var requestOptions = {
      method: "POST",
      headers: myHeaders,
      body: raw,
      redirect: "follow",
    };

    fetch(CHARGEMASTERCHARGES, requestOptions)
      .then((response) => {
        if (response.ok) return response.json();
        throw new Error(
          "Something Went Wrong While Posting Data " +
          response.status +
          " Error Code"
        );
      })
      .then((result) => {
        var chargeList = result.data;
        if (!chargeList) {
          setSearchChargeWardList(searchChargeWardList);
          setSearchChargeWardList1(searchChargeWardList);
          setWardSelectedArray([]);
        } else {
          var wardLists = chargeList[0].wardList;
          const amount = chargeList[0].amount ?? 0;
          document.getElementById("hdncharge").value = amount
          document.getElementById("quantity").value = 1;
          setUnitPrice(amount);
          setChargeAmount(amount * qty);
          document.getElementById("amount").value = amount;
          setChargeAmount(amount);
          console.log("value.amount", amount);

          for (const i in wardLists) {
            wardLists[i].nanoId = nanoid();
            wardLists[i].wardname = wardLists[i].name;
          }
          setSearchChargeWardList(wardLists);
          setSearchChargeWardList1(wardLists);
          setWardSelectedArray([]);
        }
      })
      .catch((error) => {
        console.error("error ", error);
      });
  };

