  const saveNewProductsHandler = async () => {
    const loactiontype = localStorage.getItem("INVENTORYLOCATIONTYPE");
    const headers = apiHeaders(0);
    setNewProductLoading(true);
    try {
      if (PRODUCTLIST.length === 0) {
        swal({
          text: "Please Add Products To Save...!",
          timer: 2000,
          icon: "error",
          buttons: false,
        });
        setNewProductLoading(false);
        return;
      }
      if (LOCATIONIDLIST.length === 0) {
        swal({
          text: `Please Select ${procurementBy}...!`,
          timer: 2000,
          icon: "error",
          buttons: false,
        });
        setNewProductLoading(false);
        return;
      }
      const updatedProductList = PRODUCTLIST.map(
        ({ subCategoryName, categoryName, brandName, ...rest }) => rest,
      );
      const response = await apiRequest(
        SAVECATALOUGE,
        "POST",
        {
          productMasterDTOList: updatedProductList,
          retailerIdList: loactiontype === "RETAILER" ? LOCATIONIDLIST : [],
          warehouseIdList: loactiontype !== "RETAILER" ? LOCATIONIDLIST : [],
        },
        headers,
        "json",
      );
      if (response.status_code === 200) {
        swal({
          text: `${response.message}`,
          timer: 2000,
          icon: "success",
          buttons: false,
        });
        setPRODUCTLIST([]);
        setManufacturerId(0);
        setManufacturerName("");
        setLOCATIONSELECTEDLIST([]);
        setLOCATIONIDLIST([]);
        setMaxqty(0);
        setMinqty(0);
        setHsn(0);
        setPack(0);
        setNewProductLoading(false);
        handelcreateNewProductModal();
      }
    } catch (error) {
      console.error(error.message);
      setNewProductLoading(false);
    }
  };

