      productName: newProductName,
      productCode: newProductCode,
      categoryId: categoryId,
      categoryName: categoryName,
      subCategoryId: subCategoryId,
      subCategoryName: subCategoryName,
      brandId: BRANDID,
      brandName: BRANDNAME,
