  const uploadDocs = () => {
    var files = document.getElementById("docUploadBtn").files;
    var upFiles = document.getElementById("docUploadBtn").files[0];
    var name = upFiles.name;
    var lastModified = upFiles.lastModified;
    var webkitRelativePath = upFiles.webkitRelativePath;
    var size = upFiles.size;
    var type = upFiles.type;

    const fileMb = size / 1024 ** 2;
    if (fileMb >= 2) {
      swal({
        text: "File Size must be less than or equal to 2mb....!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    if (
      type === "application/pdf" ||
      type === "image/png" ||
      type === "image/jpeg" ||
      type === "image/jpg"
    ) {
      if (type === "image/jpeg") {
        type = "image/jpg";
      }
      var selectedFileType = document.getElementById("typeSelected").value;
      var patient_id;
      var practitioner_id;
      var condition_id;
      var ipdId;
      var patientRecord = JSON.parse(sessionStorage.getItem("PatientDataArray"));
      if (patientRecord) {
        for (const i in patientRecord) {
          patient_id = patientRecord[i].clientid
            ? patientRecord[i].clientid
            : 0;
          practitioner_id = patientRecord[i].practitionerid
            ? patientRecord[i].practitionerid
            : 0;
          condition_id = patientRecord[i].conditionid
            ? patientRecord[i].conditionid
            : 0;
          ipdId = patientRecord[i].admissionid
            ? patientRecord[i].admissionid
            : 0;
        }
      }

      var uploadNotes = document.getElementById("uploadFileNote").value;
      // var files = document.getElementById("docUploadBtn").files;
      var upFiles = document.getElementById("docUploadBtn").files[0];
      var selectedFileType = document.getElementById("typeSelected").value;
      const reader = new FileReader();
      reader.readAsDataURL(upFiles);
      reader.onloadend = function () {
        const fileData = reader.result;
        var userID = localStorage.getItem("UserId");

        const localFiles = {
          patientId: patient_id,
          description: uploadNotes,
          practitionerId: practitioner_id,
          conditionId: condition_id,
          uploadby: userID,
          documentType: selectedFileType,
          fileName: name,
          ipdOrOpd: ipdId, //in case of ipd store ipd id in OPD store appointmentId
          fileDataUrl: fileData,
          fileType: type,
        };
        localFileArrayList = [...localFileArray, localFiles];
        let isFileExist = false;
        if (localFileArrayList.length == 0) {
          localFileArrayList.push(localFiles);
          setLocalFiles(localFileArrayList);
        } else {
          localFileArrayList.pop();
          for (var i = 0; i < localFileArrayList.length; i++) {
            if (localFileArrayList[i].fileName == localFiles.fileName) {
              isFileExist = true;
            }
          }
        }
        if (isFileExist) {
          swal({
            text: "File Already Added...!",
            timer: 2000,
            icon: "error",
            buttons: false,
          });
        } else {
          localFileArrayList.push(localFiles);
          setLocalFiles(localFileArrayList);
        }

        for (var i = 0, l = files.length; i < l; i++) {
          var file = files[i].name;
          const fileNameList = {
            id: "0",
            name: file,
          };
          newFileArray = [...fileList, fileNameList];
          let isFileExist = false;
          if (localFileArrayList.length == 0) {
            newFileArray.push(fileNameList);
            setFileList(newFileArray);
          } else {
            newFileArray.pop();
            for (var i = 0; i < newFileArray.length; i++) {
              if (newFileArray[i].name == fileNameList.name) {
                isFileExist = true;
              }
            }
          }
          if (isFileExist) {
            console.clear();
          } else {
            newFileArray.push(fileNameList);
            setFileList(newFileArray);
          }
        }
      };
    } else {
      swal({
        text: "Please select correct file...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
  };

