  const searchBedPatient = (e) => {
    e.preventDefault();
    var searchedData = document.getElementById("searchData").value;
    if (!searchedData) {
      swal({
        text: "Please Enter Search Text...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    if (!searchedData.replace(/\s/g, "").length) {
      swal({
        text: "Please Enter Search Text...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var newSearchedData = searchedData.trim();
    var ipdBranchId = localStorage.getItem("branch_id");
    var selecteWardId = localStorage.getItem("SELECTEDIPDWARDID");
    setLoading(true);

    var userID = localStorage.getItem("UserId");
    var branchID = localStorage.getItem("branch_id");
    var clinicid = localStorage.getItem("ClinicId");

    var myHeaders = apiHeaders(0);

    var raw = JSON.stringify({
      branchid: ipdBranchId,
      filterWardId: selecteWardId,
      searchText: newSearchedData,
      patientFrom: 0,
      showTpPatient: ACCESSAUTHDATA.Show_TP_patientonly || false,
    });

    var requestOptions = {
      method: "POST",
      headers: myHeaders,
      redirect: "follow",
      body: raw,
    };

    fetch(IPDWARDBED, requestOptions)
      .then((response) => response.json())
      .then((result) => {
        var data = result;
        var newpackageArray = [];
        for (const i in data) {
          if (data[i].dob) {
            if (data[i].dob.includes("-")) {
              // var tempDob = (data[i].dob).split("-");
              // var dob = tempDob[0] + "-" + tempDob[1] + "-" + tempDob[2];
              // var mdate = dob.toString();
              // var dobYear = parseInt(mdate.substring(0, 4), 10);
              // var dobMonth = parseInt(mdate.substring(5, 7), 10);
              // var dobDate = parseInt(mdate.substring(8, 10), 10);
              // var today = new Date();
              // var birthday = new Date(dobYear, dobMonth - 1, dobDate);
              // var diffInMillisecond = today.valueOf() - birthday.valueOf();
              // var year_age = Math.floor(diffInMillisecond / 31536000000);
              // var day_age = Math.floor((diffInMillisecond % 31536000000) / 86400000);
              // var month_age = Math.floor(day_age / 30);
              // var currentDate = new Date();
              // var currentDay = String(currentDate.getDate()).padStart(2, '0');
              // var dobDate = Number(tempDob[2]);
              // var todayDate = Number(currentDay);
              // var userDOBDays;
              // if (dobDate > todayDate) {
              //     userDOBDays = dobDate - todayDate;
              // } else if (dobDate < todayDate) {
              //     userDOBDays = todayDate - dobDate;
              // }
              // if (!userDOBDays) {
              //     userDOBDays = 0;
              // }
              // if (!year_age) {
              //     year_age = 0;
              // }
              // if (!month_age) {
              //     month_age = 0;
              // }
              // data[i].newAge = year_age + "Y " + month_age + "M " + userDOBDays + "D";
              let today = new Date();
              let dob = new Date(data[i].dob);
              let diff = today.getTime() - dob.getTime();

              // Convert milliseconds into years
              let years = Math.floor(diff / 31536000000);

              // Calculate remaining days after subtracting years
              let days_diff = Math.floor((diff % 31536000000) / 86400000);
              // Calculate months based on an average month length
              let months = Math.floor(days_diff / 30.4167);
              // Calculate remaining days after subtracting months
              let days = Math.ceil(days_diff % 30.4167);
              data[i].newAge = years + "Y " + months + "M " + days + "D";
            }
          }

          var packagedata = data[i].packageData;
          if (packagedata) {
            const expiryDate = new Date(packagedata.packageValidToDate);
            const startDate = new Date(packagedata.validPackageFromDate);
            const formattedExpiryDate = `${expiryDate.getDate()}/${expiryDate.getMonth() + 1
              }/${expiryDate.getFullYear()}`;
            const formattedStartDate = `${startDate.getDate()}/${startDate.getMonth() + 1
              }/${startDate.getFullYear()}`;

            // Update the data with the formatted dates
            packagedata.formattedExpiryDate = formattedExpiryDate;
            packagedata.formattedStartDate = formattedStartDate;
          }
        }
        var i = data.length - 1;
        for (i; i >= 0; i--) {
          if (!data[i].wardname) {
            data.splice(i, 1);
          }
        }
        data = data.filter((obj, pos, arr) => {
          return arr.map((mapObj) => mapObj.bedid).indexOf(obj.bedid) == pos;
        });
        let sortedData = data.slice().sort((a, b) => a.bedid - b.bedid);
        var jobTitle = localStorage.getItem("PRACTHASDIARY");
        if (jobTitle === "true") {
          var userID = Number.parseInt(localStorage.getItem("USERNUMERICID"));
          const filteredArray = sortedData.filter((item) => {
            const isPractitionerMatch =
              item.practitionerid &&
              parseInt(item.practitionerid) === parseInt(userID);
            const isActive = item.active === 1 || item.active === 0;
            return isPractitionerMatch && isActive;
          });

          if (filteredArray.length > 0) {
            setLoading(true);
            setFilterData(filteredArray);
            setWardBed(filteredArray);
            setSearchedWardBed(filteredArray);
          } else {
            setLoading(true);
            setFilterData(sortedData);
            setWardBed(sortedData);
            setSearchedWardBed(sortedData);
          }
        } else {
          setLoading(true);
          setFilterData(sortedData);
          setWardBed(sortedData);
          setSearchedWardBed(sortedData);
        }
        setLoading(false);
      })
      .catch((error) => console.error("error", error));
  };

