  const applyChargePackages = () => {
    var userID = localStorage.getItem("UserId");
    var patientData = JSON.parse(sessionStorage.getItem("PatientDataArray"));
    var patientId;
    var addmissionID;
    var patientName;
    var practitionerName;
    var practitionerId;
    for (var i = 0; i < patientData.length; i++) {
      patientId = patientData[i].clientid;
      addmissionID = patientData[i].admissionid;
      patientName = patientData[i].patient_name;
      practitionerName = patientData[i].practitioner_name;
      practitionerId = patientData[i].practitionerid;
    }
    var fromDate = document.getElementById("packageFormDate").value;
    if (!fromDate) {
      swal({
        text: "Please Select From Date...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var toDate = document.getElementById("packageToDate").value;
    if (!toDate) {
      swal({
        text: "Please Select To Date...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }

    var chargeTypeLvlCheck = document.getElementById("chargeTypeLevel");
    var chargeTypeLvl;
    if (chargeTypeLvlCheck.checked === true) {
      chargeTypeLvl = 1;
    } else {
      chargeTypeLvl = 0;
    }
    const currentTime = packageCurrTime;
    if (!currentTime) {
      swal({
        text: "Please Select Time...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var branchid = localStorage.getItem("branch_id");

    var userID = localStorage.getItem("UserId");
    var branchID = localStorage.getItem("branch_id");
    var clinicid = localStorage.getItem("ClinicId");

    var myHeaders = apiHeaders(patientId);

    fetch(APPLYPACKAGE, {
      method: "POST",
      headers: myHeaders,
      body: JSON.stringify({
        addmisionid: addmissionID || IPDID,
        amount: PACKAGEAMOUNT,
        applied_by_userid: userID,
        apply_at_chargetype_level: chargeTypeLvl,
        days: PACKAGEEXPIRYDAYS,
        fromdate_time: fromDate + " " + currentTime,
        packageid: PACKAGEID,
        patientid: patientId,
        todate_time: toDate + " " + currentTime,
        packagename: PACKAGENAME,
        patientname: patientName,
        practitioner_name: practitionerName,
        practitionerid: practitionerId,
        branchid: branchid,
        opd_appointmentid: 0,
      }),
    })
      .then((response) => {
        if (response.ok) return response.json();
        throw new Error(
          "Something Went Wrong While Posting Data " +
          response.status +
          " Error Code",
        );
      })
      .then((data) => {
        if (data.id !== 0) {
          swal({
            text: "Package Applied Successfully...!",
            timer: 2000,
            icon: "success",
            buttons: false,
          });

          document.getElementById("packageFormDate").value = "";
          document.getElementById("packageToDate").value = "";
          document.getElementById("chargeTypeLevel").checked = false;
          document.getElementById("closePackageModal").click();
          setChargeSelectedValidation(false);
          setPackageName("");
          sePackageNameId("");
          setPackageExpiryDays("");
          setPackageAmount("");
          getUpdatedIPDBed();
        } else {
          swal({
            text: "Something Went Wrong...!",
            timer: 2000,
            icon: "error",
            buttons: false,
          });
        }
      })
      .catch((error) => {
        console.error(error.message);
      });
  };

