  const getChargeNameListAccChargeType = (chargeTypeId) => {
    var patientRecord = JSON.parse(sessionStorage.getItem("PatientDataArray"));
    var getPayee;
    var wardId;
    var thirdPartyId;
    var wardRateChange;
    for (var i = 0; i < patientRecord.length; i++) {
      getPayee = patientRecord[i].whopay;
      wardId = Number(patientRecord[i].wardid);
      wardRateChange = Number(patientRecord[i].wardRateChange);
      thirdPartyId = patientRecord[i].tpid;
    }
    if (wardRateChange !== 0) {
      wardId = wardRateChange;
    }
    setPayee(getPayee);
    if (getPayee === "Self") {
      var tdId = 0;
    } else {
      var tdId = thirdPartyId;
    }
    var wardId;
    if (!wardId) {
      wardId = 0;
    }
    var chrTypeId = chargeTypeId ? chargeTypeId : null;
    if (!chrTypeId) {
      chrTypeId = null;
    }
    if (!wardId) {
      wardId = 0;
    }

    var userID = localStorage.getItem("UserId");
    var branchID = localStorage.getItem("branch_id");
    var clinicid = localStorage.getItem("ClinicId");

    var myHeaders = apiHeaders(0);

    var raw = JSON.stringify({
      chargeTypeId: chrTypeId,
      practitionerid: null,
      showWard: false,
      thirdPartyId: tdId,
      wardid: wardId,
      searchKey: null,
      campId: campId,
    });

    var requestOptions = {
      method: "POST",
      headers: myHeaders,
      body: raw,
      redirect: "follow",
    };

    fetch(DETAILEDCHARGENAMELIST, requestOptions)
      .then((response) => response.json())
      .then((result) => {
        if (result.status_code == 200) {
          var response = result.data;
          var chargeList = response.list || [];
          if (chargeList.length == 0) {
            setChargeTypeLoading(false);
          } else {
            const allCharges = {
              amount: null,
              chargeTypeId: null,
              code: null,
              id: 0,
              name: "Select Charge",
              refralShareAmount: 0,
            };
            chargeList.push(allCharges);
            chargeList = chargeList.filter((obj, pos, arr) => {
              return arr.map((mapObj) => mapObj.name).indexOf(obj.name) == pos;
            });
            let sortedChargeList = chargeList
              .slice()
              .sort((a, b) => a.id - b.id);
            setChargeNameArray(sortedChargeList);
            setChargeTypeLoading(true);
          }
        }
      })
      .catch((error) => console.error("error", error));
  };

