  const addChargeHandler = (chargeGrpDiscount) => {
    var date = new Date(dateSelected);
    var commencing = new Date(
      date.getFullYear(),
      date.getMonth(),
      date.getDate(),
    );
    var dd = String(commencing.getDate()).padStart(2, "0");
    var mm = String(commencing.getMonth() + 1).padStart(2, "0");
    var yyyy = commencing.getFullYear();
    commencing = dd + "-" + mm + "-" + yyyy;
    var chargeDate = yyyy + "-" + mm + "-" + dd;

    var getPaidBy = payee;
    var getChargeType = chargeTypeName || RATELISTCHARGETYPENAME2;
    var newGetChargeTypeName = getChargeType.replace(/^\s+|\s+$/gm, "");

    var practId = Number(ACpractionerID);
    if (!practId) {
      practId = 0;
    }

    var practName = ACpractionerName;
    if (!practName) {
      practName = "";
    }

    var sicltyName = specialityName;
    if (!sicltyName) {
      sicltyName = "";
    }

    getChargeType = newGetChargeTypeName;
    if (!getChargeType) {
      swal({
        text: "Please Select Charge Type...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var getChargeName = chargeName || RATEDLISTCHARGENAME1;
    var newGetChargeTypeName = getChargeName.replace(/^\s+|\s+$/gm, "");
    getChargeName = newGetChargeTypeName;
    if (!getChargeName) {
      swal({
        text: "Please Select Charge...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var patientData = JSON.parse(sessionStorage.getItem("PatientDataArray"));
    for (const i in patientData) {
      var practitionerName = patientData[i].practitioner_name;
    }
    var getQty = document.getElementById("quantity").value;
    if (!getQty || getQty === "0") {
      // getQty = 0; // Changed Because of new requirement JIRA Task Number SC22-2175
      swal({
        text: "Please Enter Quantity...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var getUnitPrice = document.getElementById("hdncharge").value;
    var getAmount = document.getElementById("amount").value;
    var getChargeId = chargeId;

    if (getChargeType === null || getChargeType === undefined) {
      swal({
        text: "Please select Charge Type...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
    } else if (getChargeName === null || getChargeName === undefined) {
      swal({
        text: "Please select Charge Name...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      let handleChargeName = ACCESSAUTHDATA?.sclyte_hide_practitionername
        ? getChargeName
        : getChargeName + ACpractionerName;
      if (CMPLCOUNSLTANTVALIDATION) {
        {
          // practitionerName
          //   ? (getChargeName = getChargeName + " - " + practitionerName)
          //   : (getChargeName = getChargeName);

          practitionerName
            ? (getChargeName = handleChargeName)
            : (getChargeName = handleChargeName);
        }
      } else {
        if (ACCESSAUTHDATA.sclyte_addcharge_cmppractitionername) {
          // getChargeName = practitionerName
          //   ? `${getChargeName} - ${practitionerName}`
          //   : getChargeName;

          practitionerName
            ? (getChargeName = handleChargeName)
            : (getChargeName = handleChargeName);
        } else {
          getChargeName = getChargeName;
        }
      }
    } else if (getQty === null || getQty === undefined) {
      swal({
        text: "Please Enter Quantity...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
    } else if (getUnitPrice === null || getUnitPrice === undefined || getUnitPrice === "") {
      swal({
        text: "Please Enter Unit Price...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    } else if (Number(getUnitPrice) === 0 && !ACCESSAUTHDATA.disable_zeroamt) {
      swal({
        text: "Unit Price cannot be zero. Please Enter Unit Price...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    } else {
      var chargeTPCode = chargeCode;
      if (!chargeTPCode) {
        chargeTPCode = "0";
      }

      var chargeDiscountpercent = chargeDiscount;
      if (!chargeDiscountpercent) {
        chargeDiscountpercent = 0;
      }

      var nanoId = nanoid();
      var discountTypeTag = "DiscountType" + nanoId;
      var discountAmountTag = "DiscountAmountTag" + nanoId;
      var isManualChargeValidation = false;
      if (getChargeId == 0) {
        isManualChargeValidation = true;
      }
      const addNewCharge = {
        date: commencing,
        chargeDate: chargeDate,
        chargeid: getChargeId || RATEDLISTCHARGEID1,
        chargetype: getChargeType,
        unitprice: getUnitPrice,
        qty: getQty,
        sicltyName: sicltyName,
        paidBy: getPaidBy,
        chargeName: getChargeName,
        amount: chargeDiscountpercent ? getAmount : getUnitPrice * getQty,
        defaultAmount: getAmount,
        discountType: "",
        discountAmount: 0,
        discount: 0,
        discountTypeTag: chargeDiscountpercent > 0 ? 0 : discountTypeTag,
        discountAmountTag:
          chargeDiscountpercent > 0 ? chargeDiscountpercent : discountAmountTag,
        getChargeTypeID: chargeTypeId || CHARGETYPEID2,
        isManualCharge: isManualChargeValidation,
        chargeCode: chargeTPCode,
        defaultDiscount: false,
        charge_practitioner_id: Number(practId),
        charge_practitioner_name: practName,
        associatePractitionerId: assPractitionerId || 0,
        associatePractitionerName: assPractitionerName || ""
      };
      if (chargeGrpDiscount) {
        var chargeAmt = addNewCharge.amount;
        var discountInPercent = Number(chargeGrpDiscount) / 100;
        var totaldic = Number(chargeAmt * discountInPercent);
        addNewCharge.discountAmount = Number.parseFloat(totaldic).toFixed(2);
        addNewCharge.discount = Number(chargeGrpDiscount);
        addNewCharge.defaultDiscount = true;
        var afterDiscountAmount = Number.parseFloat(
          Number(chargeAmt) - Number(totaldic),
        ).toFixed(2);
        addNewCharge.amount = afterDiscountAmount;
        addNewCharge.oldInputQty = nanoid();
        addNewCharge.oldInputUnit = nanoid();
        addNewCharge.discountType = 1;
        addNewCharge.discountTypeTag = discountTypeTag;
        addNewCharge.discountAmountTag = discountAmountTag;
        // addNewCharge.defaultAmount = Number.parseFloat(Number(addNewCharge.unitprice) * Number(addNewCharge.qty)).toFixed(2);
        addNewCharge.defaultAmount = Number.parseFloat(
          Number(addNewCharge.amount),
        ).toFixed(2);
      } else {
        addNewCharge.oldInputQty = nanoid();
        addNewCharge.oldInputUnit = nanoid();
        addNewCharge.discountType = chargeDiscountpercent > 0 ? 0 : "";
        var afterDiscountAmount = Number.parseFloat(
          Number(chargeAmt) -
          Number.parseFloat(
            (chargeAmt * chargeDiscountpercent) / 100,
          ).toFixed(2),
        );
        addNewCharge.discountAmount = Number.parseFloat(
          Number.parseFloat(chargeAmt) *
          Number.parseFloat(chargeDiscountpercent / 100),
        );
        addNewCharge.discount =
          chargeDiscountpercent > 0 ? chargeDiscountpercent : 0;
        addNewCharge.discountTypeTag = discountTypeTag;
        addNewCharge.discountAmountTag = discountAmountTag;
        // addNewCharge.defaultAmount = Number.parseFloat(Number(addNewCharge.unitprice) * Number(addNewCharge.qty)).toFixed(2);
        // addNewCharge.amount = Number.parseFloat(Number(addNewCharge.unitprice) * Number(addNewCharge.qty)).toFixed(2);
        addNewCharge.defaultAmount = Number.parseFloat(
          Number(addNewCharge.amount),
        ).toFixed(2);
        addNewCharge.amount = Number.parseFloat(
          Number(addNewCharge.amount),
        ).toFixed(2);
      }
      addNewChargeArray = [...chargeList, addNewCharge];
      let isChargeExist = false;
      if (addNewChargeArray.length == 0) {
        addNewChargeArray.push(addNewCharge);
        setChargeList(addNewChargeArray);
        var totalAmount = 0.0;
        for (const i in addNewChargeArray) {
          var qty = addNewChargeArray[i].qty;
          var amount = addNewChargeArray[i].amount;
          // var totalAmt = Number(qty) * Number(amount);
          var totalAmt = Number(amount);
          totalAmount = Number(totalAmount) + Number(totalAmt);
          setTotalChargeAmount(totalAmount);
        }
      } else {
        addNewChargeArray.pop();
        for (var i = 0; i < addNewChargeArray.length; i++) {
          if (!addNewChargeArray[i].isManualCharge) {
            if (
              addNewChargeArray[i].chargeid == addNewCharge.chargeid &&
              addNewChargeArray[i].date == addNewCharge.date
            ) {
              // if (addNewChargeArray[i].chargeid == (addNewCharge.chargeid) && addNewChargeArray[i].charge_practitioner_id == (addNewCharge.charge_practitioner_id)) { Changed Because of new requirements SC22-2355
              isChargeExist = true;
            }
          }
        }
      }
      if (isChargeExist) {
        swal({
          text: "Charge Already Added",
          timer: 2000,
          icon: "error",
          buttons: false,
        });
      } else {
        addNewChargeArray.push(addNewCharge);
        setChargeList(addNewChargeArray);
        var totalAmount = 0.0;
        for (const i in addNewChargeArray) {
          var qty = addNewChargeArray[i].qty;
          var amount = addNewChargeArray[i].amount;
          // var totalAmt = Number(qty) * Number(amount);
          var totalAmt = Number(amount);
          totalAmount = Number(totalAmount) + Number(totalAmt);
          setTotalChargeAmount(totalAmount);
        }
      }
      document.getElementById("quantity").value = "";
      document.getElementById("hdncharge").value = "";
      document.getElementById("amount").value = "";
      setChargeId("");
      setChargeName("");
      setSpecialityName("");
      setQty(0);
      setUnitPrice(0);
      setChargeAmount(0);
      setChargeTypeId("");
      setChargeTypeName("");
      setChargeNameArray([]);
      setChargeDiscount("");
      if (ACCESSAUTHDATA.sclyte_disable_manualcharge) {
        setSearchChargeName("");
      }
    }
  };

  const Genericnamehandel = (value) => {
    setSelectedGenericname(value.genericName);
    setSelectedGenericId(value.id);
  };

  const addChargeHandlerIfExists = () => {
    var patientRecord = JSON.parse(sessionStorage.getItem("PatientDataArray"));
    var getPayee = "";
    // var wardId;
    // for (var i = 0; i < patientRecord.length; i++) {
    //     wardId = patientRecord[i].wardid;
    //     if (wardId === null || wardId === undefined) {
    //         wardId = "0";
    //     }
    // }
    // var tpId = PATIENTTHIRDPARTYID;
    // if (tpId == 0) {
    //     getPayee = "Self";
    // } else {
    //     getPayee = "Third Party";
    // }

    var date = new Date(dateSelected);
    var commencing = new Date(
      date.getFullYear(),
      date.getMonth(),
      date.getDate(),
    );
    var dd = String(commencing.getDate()).padStart(2, "0");
    var mm = String(commencing.getMonth() + 1).padStart(2, "0");
    var yyyy = commencing.getFullYear();
    commencing = dd + "-" + mm + "-" + yyyy;
    var chargeDate = yyyy + "-" + mm + "-" + dd;

    var getChargeType = chargeTypeName;
    var newGetChargeType = getChargeType.replace(/^\s+|\s+$/gm, "");
    getChargeType = newGetChargeType;
    if (!getChargeType) {
      swal({
        text: "Please Select Charge Type...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var getChargeTypeID = chargeTypeId;
    if (!getChargeTypeID) {
      swal({
        text: "Please Select Charge Type...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var getChargeName = chargeName;
    var newGetChargeName = getChargeName.replace(/^\s+|\s+$/gm, "");
    getChargeName = newGetChargeName;
    if (!getChargeName) {
      swal({
        text: "Please Select Charge...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var getQty = document.getElementById("quantity").value;
    if (getQty === "0") {
      // getQty = 0; // Changed Because of new requirement JIRA Task Number SC22-2175
      swal({
        text: "Please Enter Quantity...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var getUnitPrice = document.getElementById("hdncharge").value;
    var getAmount = document.getElementById("amount").value;
    var getChargeId = chargeId;
    if (!getChargeId) {
      getChargeId = 0;
    }
    // var manualChargeName = document.getElementById("manualChargeTxt").value;
    var isManualCharge = false;
    if (getChargeId == 0) {
      isManualCharge = true;
    }
    if (!getQty) {
      swal({
        text: "Please Enter Quantity...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    } else if (getUnitPrice === null || getUnitPrice === undefined) {
      swal({
        text: "Please Enter Unit Price...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }

    // ===== DISABLE ZERO AMOUNT VALIDATION =====
    if (!ACCESSAUTHDATA.disable_zeroamt) {
      const totalAmount = Number(getUnitPrice) * Number(getQty);
      if (totalAmount <= 0) {
        swal({
          text: "Cannot add charge with zero amount. Please enter a valid amount...!",
          timer: 3000,
          icon: "error",
          buttons: false,
        });
        return;
      }
    }

    var practId = Number(ACpractionerID);
    if (!practId) {
      practId = 0;
    }

    var practName = ACpractionerName;
    if (!practName) {
      practName = "";
    }

    var sicltyName = specialityName;
    if (!sicltyName) {
      sicltyName = "";
    }

    var practSpecialization = ACpractionerSpecialization;
    if (!practSpecialization) {
      practSpecialization = "0";
    }

    var nanoId = nanoid();
    var discountTypeTag = "DiscountType" + nanoId;
    var discountAmountTag = "DiscountAmountTag" + nanoId;

    var practChargeName = "";
    {
      practName
        ? (practChargeName =
          getChargeName + "  /  " + practName + " / " + sicltyName)
        : (practChargeName = getChargeName);
    }
    if (CMPLCOUNSLTANTVALIDATION) {
      {
        chargePractitionerName
          ? (practChargeName = getChargeName + " - " + chargePractitionerName)
          : (practChargeName = getChargeName);
      }
      {
        chargePractitionerName
          ? (getChargeName =
            getChargeName +
            " - " +
            chargePractitionerName +
            "  " +
            specialityName)
          : (getChargeName = getChargeName);
      }
      practId = chargePractitionerId;
      practName = chargePractitionerName;
    } else {
      if (ACCESSAUTHDATA.sclyte_addcharge_cmppractitionername) {
        practChargeName = chargePractitionerName
          ? `${getChargeName} - ${chargePractitionerName}`
          : getChargeName;
        getChargeName = chargePractitionerName
          ? `${getChargeName} - ${chargePractitionerName}  ${specialityName}`
          : getChargeName;
      } else {
        practChargeName = getChargeName;
      }
    }
    var chargeTPCode = chargeCode;
    if (!chargeTPCode) {
      chargeTPCode = "0";
    }

    const addNewCharge = {
      date: commencing,
      chargedate: chargeDate,
      chargeid: getChargeId,
      chargetype: getChargeType,
      chargetypeId: getChargeTypeID,
      unitprice: 0,
      qty: getQty,
      sicltyName: sicltyName,
      paidBy: getPayee,
      chargeName: getChargeName,
      defaultChargeName: practChargeName,
      amount: 0,
      charge_practitioner_id: Number(practId),
      charge_practitioner_name: practName,
      specialization_id: practSpecialization,
      defaultAmount: 0,
      discountType: 1,
      discountAmount: 0,
      discount: 0,
      campChargeDiscount: 0,
      discountTypeTag: discountTypeTag,
      discountAmountTag: discountAmountTag,
      manualCharge: isManualCharge,
      chargeCode: chargeTPCode,
      originalChargeAmount: getUnitPrice,
      associatePractitionerId: assPractitionerId || 0,
      associatePractitionerName: assPractitionerName || ""
    };
    addNewChargeArray = [...chargeList, addNewCharge];
    let isChargeExist = false;
    if (addNewChargeArray.length == 0) {
      addNewChargeArray.push(addNewCharge);
      setChargeList(addNewChargeArray);
    } else {
      addNewChargeArray.pop();
      for (var i = 0; i < addNewChargeArray.length; i++) {
        if (addNewChargeArray[i].chargeid !== 0) {
          if (
            addNewChargeArray[i].chargeid == addNewCharge.chargeid &&
            addNewChargeArray[i].charge_practitioner_id ==
            addNewCharge.charge_practitioner_id &&
            addNewChargeArray[i].chargedate == addNewCharge.chargedate
          ) {
            // if (addNewChargeArray[i].chargeid == (addNewCharge.chargeid) && addNewChargeArray[i].charge_practitioner_id == (addNewCharge.charge_practitioner_id)) { Changed Because of new requirements SC22-2355
            isChargeExist = true;
          }
        }
      }
    }
    if (isChargeExist) {
      swal({
        text: "Charge Already Added",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
    } else {
      addNewChargeArray.push(addNewCharge);
      setChargeList(addNewChargeArray);
    }

    document.getElementById("createChargeBtn").disabled = false;
    document.getElementById("createInvoiceBtn").disabled = false;
    document.getElementById("viewEstimateBtn").disabled = false;
    document.getElementById("cashDeskBtn").disabled = false;

    // document.getElementById("manualChargeTxt").value = "";
    document.getElementById("quantity").value = "";
    document.getElementById("hdncharge").value = "";
    document.getElementById("amount").value = "";

    setChargeId("");
    setChargeName("");
    setUnitPrice(0);
    setQty(0);
    setChargeAmount("");
    // setACPractitionerId(0);
    // setACPractitionerName("");
    // setACPractitionerSpecialization("");
    setChargeTypeId("");
    setChargeTypeName("");
    setChargeNameArray([]);
    setChargeDiscount(0);
    if (ACCESSAUTHDATA.sclyte_disable_manualcharge) {
      setSearchChargeName("");
    }
  };

