  const addNewWardChargesAftershiftBed = async () => {
    try {
      const whoPayId = SHIFTPATIENTINFO.tpid ? SHIFTPATIENTINFO.tpid : 0;
      var whoPay = "Client";
      if (whoPayId === 0) {
        whoPay = "Client";
      } else {
        whoPay = "Third Party";
      }
      const branchID = localStorage.getItem("branch_id");
      const headers = apiHeaders(SHIFTPATIENTINFO.clientid);
      const applyNewChargesResult = await apiRequest(
        SHIFTIPDBEDCHARGES,
        "POST",
        {
          wardid: SHIFTBEDWARDID,
          thirdparty_id: SHIFTPATIENTINFO.tpid ? SHIFTPATIENTINFO.tpid : 0,
          practitionerid: SHIFTPATIENTINFO.practitionerid
            ? SHIFTPATIENTINFO.practitionerid
            : 0,
          practitionername: SHIFTPATIENTINFO.practitioner_name
            ? SHIFTPATIENTINFO.practitioner_name
            : "",
          patientname: SHIFTPATIENTINFO.patient_name,
          patientid: SHIFTPATIENTINFO.clientid,
          admission_id: SHIFTPATIENTINFO.admissionid,
          branch_id: branchID,
          whopay: whoPay,
          appliedNewStandardCharges: ACCESSAUTHDATA.sclyte_standard_charge
            ? true
            : false,
        },
        headers,
        "json",
      );
      if (applyNewChargesResult.status_code) {
        setShiftBedId("");
        setShiftBedName("");
        setShiftBedWardId("");
        setShiftBedWardName("");
        setPatientBedShiftInfo({});
        getIPDBed();
      }
    } catch (error) {
      console.error(error.message);
    }
  };

  const changeDiscountAmount = (item) => {
    var chargeData = [...chargeList];
    var discountType = document.getElementById(item.discountTypeTag).value;
    item.discountAmt = 0;
    item.amount = item.defaultAmount;
    if (discountType === "2") {
      var totalPayableAmt = Number(item.defaultAmount);
      document.getElementById(item.discountAmountTag).value = 100;
      document.getElementById(item.discountAmountTag).disabled = true;
      var discountInPercent = Number(100) / 100;
      var totaldic = Number(totalPayableAmt * discountInPercent);
      item.discountAmount = Number.parseFloat(totaldic).toFixed(2);
      item.discount = Number.parseFloat(100).toFixed(2);
      var afterDiscountAmount = Number.parseFloat(
        Number(totalPayableAmt) - Number(totaldic),
      ).toFixed(2);
      item.amount = afterDiscountAmount;
      item.discountType = 0;
    } else {
      item.discount = 0;
      item.discountType = discountType;
      document.getElementById(item.discountAmountTag).value = "";
      document.getElementById(item.discountAmountTag).disabled = false;
    }
    setChargeList(chargeData);
  };

  const calculateDiscount = (item) => {
    var chargeData = [...chargeList];
    var discountAmt = document.getElementById(item.discountAmountTag).value;
    var discountType = document.getElementById(item.discountTypeTag).value;
    item.discountType = discountType;
    var totalPayableAmt = Number(item.defaultAmount);
    if (discountType === "0") {
      if (Number(discountAmt) > 100) {
        swal({
          text: "Invalid discount amount...!",
          timer: 2000,
          icon: "error",
          buttons: false,
        });
        document.getElementById(item.discountAmountTag).value = "";
        return;
      }
      var discountInPercent = Number(discountAmt) / 100;
      var totaldic = Number(totalPayableAmt * discountInPercent);
      item.discountAmount = Number.parseFloat(totaldic).toFixed(2);
      item.discount = Number.parseFloat(discountAmt).toFixed(2);
      var afterDiscountAmount = Number.parseFloat(
        Number(totalPayableAmt) - Number(totaldic),
      ).toFixed(2);
      item.amount = afterDiscountAmount;

      var totalAmount = 0.0;
      for (const i in chargeData) {
        var qty = chargeData[i].qty;
        var amount = chargeData[i].amount;
        // var totalAmt = Number(qty) * Number(amount);
        var totalAmt = Number(amount);
        totalAmount = Number(totalAmount) + Number(totalAmt);
        setTotalChargeAmount(totalAmount);
      }
    } else if (discountType === "1") {
      if (Number(discountAmt) > Number(totalPayableAmt)) {
        swal({
          text: "Invalid discount amount...!",
          timer: 2000,
          icon: "error",
          buttons: false,
        });
        document.getElementById(item.discountAmountTag).value = "";
        return;
      }
      var cashDiscount = Number.parseFloat(
        Number(totalPayableAmt) - Number(discountAmt),
      ).toFixed(2);
      item.discountAmount = Number.parseFloat(discountAmt).toFixed(2);
      item.discount = Number.parseFloat(discountAmt).toFixed(2);
      item.amount = cashDiscount;

      var totalAmount = 0.0;
      for (const i in chargeData) {
        var qty = chargeData[i].qty;
        var amount = chargeData[i].amount;
        // var totalAmt = Number(qty) * Number(amount);
        var totalAmt = Number(amount);
        totalAmount = Number(totalAmount) + Number(totalAmt);
        setTotalChargeAmount(totalAmount);
      }
    } else if (discountType === "2") {
      if (Number(discountAmt) > 100) {
        swal({
          text: "Invalid discount amount...!",
          timer: 2000,
          icon: "error",
          buttons: false,
        });
        document.getElementById(item.discountAmountTag).value = "";
        return;
      }
      var discountInPercent = Number(100) / 100;
      var totaldic = Number(totalPayableAmt * discountInPercent);
      item.discountAmount = Number.parseFloat(totaldic).toFixed(2);
      item.discount = Number.parseFloat(100).toFixed(2);
      var afterDiscountAmount = Number.parseFloat(
        Number(totalPayableAmt) - Number(totaldic),
      ).toFixed(2);
      item.amount = afterDiscountAmount;
      item.discountType = 0;

      var totalAmount = 0.0;
      for (const i in chargeData) {
        var qty = chargeData[i].qty;
        var amount = chargeData[i].amount;
        // var totalAmt = Number(qty) * Number(amount);
        var totalAmt = Number(amount);
        totalAmount = Number(totalAmount) + Number(totalAmt);
        setTotalChargeAmount(totalAmount);
      }
    }
    setChargeList(chargeData);
  };

  // discharge process
  const dischargeProcessStatusHandler = () => {
    setCheckListLoading(true);
    var patientRecord = JSON.parse(sessionStorage.getItem("PatientDataArray"));
    var getDischargeId;
    for (var i = 0; i < patientRecord.length; i++) {
      getDischargeId = patientRecord[i].dischargeId;
    }
    var dischargeId = Number.parseInt(getDischargeId);
    localStorage.setItem("dischargeId", dischargeId);

    var userID = localStorage.getItem("UserId");
    var branchID = localStorage.getItem("branch_id");
    var clinicid = localStorage.getItem("ClinicId");

    var myHeaders = apiHeaders(0);

    var requestOptions = {
      method: "GET",
      headers: myHeaders,
      redirect: "follow",
    };

    fetch(DISCHARGEPROCESSLIST + dischargeId, requestOptions)
      .then((response) => response.json())
      .then((result) => {
        var stepTwoValidation = false;
        var stepThreeValidation = false;
        var stepFourValidation = false;

        var stepOneArray = [];
        var stepTwoArray = [];
        var stepThreeArray = [];
        var stepFourArray = [];

        for (const i in result) {
          if (result[i].stepid == 1) {
            if (result[i].status === "0") {
              setCompleteLoadingStep1(false);
            } else if (result[i].status === "1") {
              stepTwoValidation = true;
              setCompleteLoadingStep1(true);
            }
            stepOneArray = [...result[i].discharge_checklist_name_array];
            setDischargeFormProcessArray(
              result[i].discharge_checklist_name_array,
            );
            setDischargeStepOneDateTime(result[i].dateTime || "");
          } else if (result[i].stepid == 2) {
            if (result[i].status === "0") {
              setCompleteLoadingStep2(false);
            } else if (result[i].status === "1") {
              stepThreeValidation = true;
              setCompleteLoadingStep2(true);
            }
            stepTwoArray = [...result[i].discharge_checklist_name_array];
            setPharmacyClearanceArray(result[i].discharge_checklist_name_array);
            setDischargeStepTwoDateTime(result[i].dateTime || "");
          } else if (result[i].stepid == 3) {
            if (result[i].status === "0") {
              setCompleteLoadingStep3(false);
            } else if (result[i].status === "1") {
              stepFourValidation = true;
              setCompleteLoadingStep3(true);
            }
            stepThreeArray = [...result[i].discharge_checklist_name_array];
            setBillClearanceArray(result[i].discharge_checklist_name_array);
            setDischargeStepThreeDateTime(result[i].dateTime || "");
          } else if (result[i].stepid == 4) {
            if (result[i].status === "0") {
              setCompleteLoadingStep4(false);
            } else if (result[i].status === "1") {
              stepFourValidation = true;
              setCompleteLoadingStep4(true);
            }
            stepFourArray = [...result[i].discharge_checklist_name_array];
            setNursingClearanceArray(result[i].discharge_checklist_name_array);
            setDischargeStepFourDateTime(result[i].dateTime || "");
          }
        }
        setCheckListData(result);
        setCheckListLoading(false);

        for (const i in stepOneArray) {
          var checktag = stepOneArray[i].status;
          if (checktag === "1") {
            document.getElementById("selectAllDischargeProcess").checked = true;
          }
        }

        for (const i in stepTwoArray) {
          var checktag = stepTwoArray[i].status;
          if (checktag === "1") {
            document.getElementById("selectAllPhrma").checked = true;
          }
        }

        for (const i in stepThreeArray) {
          var checktag = stepThreeArray[i].status;
          if (checktag === "1") {
            document.getElementById("recievedMedicalRecords").checked = true;
          }
        }

        for (const i in stepFourArray) {
          var checktag = stepFourArray[i].status;
          if (checktag === "1") {
            document.getElementById("nurseClearTabCheck").checked = true;
          }
        }

        if (stepTwoValidation) {
          pharmacyClearTab();
        }
        if (stepThreeValidation) {
          billClearTab();
        }
        if (stepFourValidation) {
          nurseClearTab();
        }
        // initiateDischargeProcessHandler()
      })
      .catch((error) => console.error("error", error));
  };

  const initiateDischargeProcessHandler = async () => {
    try {
      const patientRecord =
        JSON.parse(sessionStorage.getItem("PatientDataArray")) || [];
      const Userid = localStorage.getItem("ProfileUserId");
      let dischargeId, dischargeStatus, clientId;
      for (const patientInfo of patientRecord) {
        dischargeId = patientInfo.dischargeId;
        dischargeStatus = patientInfo.discharge_status;
        clientId =
          patientInfo.clientid ||
          patientInfo.patientid ||
          patientInfo.patient_id ||
          patientInfo.patientId;
      }
      document.getElementById("getStart").style.display = "none";
      document.getElementById("getStop").style.display = "block";
      sessionStorage.setItem("PatientDataArray", JSON.stringify(patientRecord));
      localStorage.setItem("dischargeId", dischargeId);
      setpatientRecord(patientRecord);
      setDishargeStatus("1");
      const headers = apiHeaders(clientId);
      const patientid = sessionStorage.getItem("patient_id");
      const initiateDischarge = await apiRequest(
        DISCHARGESTARTSTOP,
        "POST",
        {
          dischargeid: dischargeId,
          userid: Userid,
          flag: 1,
          clientId: patientid,
        },
        headers,
        "json",
      );
      const status = initiateDischarge.message;
      if (status === "SUCCESS") {
        console.log("Discharge Inititated Successfully...!");
      }
    } catch (error) {
      console.error(error.message);
    }
  };

