  const updateStepDischargeProcess = (value) => {
    var flag = value;
    var getUserId = localStorage.getItem("UserId");
    var getDischargeId = localStorage.getItem("dischargeId");

    var userID = localStorage.getItem("UserId");
    var branchID = localStorage.getItem("branch_id");
    var clinicid = localStorage.getItem("ClinicId");

    var myHeaders = apiHeaders(0);

    var raw = JSON.stringify({
      process_number: flag,
      status: 1,
      userid: getUserId,
      dischargeid: getDischargeId,
    });

    var requestOptions = {
      method: "POST",
      headers: myHeaders,
      body: raw,
      redirect: "follow",
    };

    fetch(UPDATESTEPDISCHARGEPROCESS, requestOptions)
      .then((response) => response.json())
      .then((result) => {
        if (result) {
          if (flag == 2) {
            localStorage.setItem("VIEWACCOUTBREADCRUMBS", "IPD");
            setCompleteLoadingStep2(true);
          } else if (flag == 3) {
            localStorage.setItem("VIEWACCOUTBREADCRUMBS", "IPD");
            setCompleteLoadingStep3(true);
          } else if (flag == 4) {
            setCompleteLoadingStep4(true);
          }
        }
        dischargeProcessStatusHandler();
      })
      .catch((error) => console.error("error", error));
  };

