  const saveAllergiesHandler = () => {
    var patientData = JSON.parse(sessionStorage.getItem("PatientDataArray"));
    var patientId = sessionStorage.getItem("patient_id");

    var userID = localStorage.getItem("UserId");
    var branchID = localStorage.getItem("branch_id");
    var clinicid = localStorage.getItem("ClinicId");

    var myHeaders = apiHeaders(patientId);

    var clientId = patientId;
    var location = localStorage.getItem("Location");
    var getIpdId;
    var getOpdId;
    var getId = patientAllergyId;
    if (getId == null || getId == undefined) {
      getId = 0;
    }
    var getAllergy = document.getElementById("getAllergies").value;
    var checkSeverity = document.getElementById("getSeverity").value;
    var checkOnSet = document.getElementById("getOnset").value;
    var checkReaction = document.getElementById("getReactions").value;
    var checkDate = document.getElementById("allergyDate").value;
    if (checkDate == "" || checkDate == undefined || checkDate == null) {
      swal({
        text: "Please Select Date...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var getDate = checkDate.split("/");
    getDate = getDate[2] + "-" + getDate[1] + "-" + getDate[0];
    if (location == "OPD") {
      getIpdId = 0;
      getOpdId = localStorage.getItem("appointmentId");
    }
    if (location == "IPD") {
      getIpdId = localStorage.getItem("admissionId");
      getOpdId = 0;
    }
    if (getAllergy == "0" || getAllergy == undefined || getAllergy == null) {
      swal({
        text: "Please Select Allergy...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }

    if (
      checkSeverity == "0" ||
      checkSeverity == undefined ||
      checkSeverity == null
    ) {
      swal({
        text: "Please Select Severity...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    if (checkOnSet == "0" || checkOnSet == undefined || checkOnSet == null) {
      swal({
        text: "Please Select Onset...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    if (
      checkReaction == "" ||
      checkReaction == undefined ||
      checkReaction == null
    ) {
      swal({
        text: "Please Select Reaction...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }

    var raw = JSON.stringify({
      id: getId,
      clientid: clientId,
      ipdId: getIpdId,
      opdId: getOpdId,
      severity: checkSeverity,
      onSet: checkOnSet,
      reaction: checkReaction,
      datetime: getDate,
      allergyName: getAllergy,
    });

    var requestOptions = {
      method: "POST",
      headers: myHeaders,
      body: raw,
      redirect: "follow",
    };

    fetch(SAVEALLERGIES, requestOptions)
      .then((response) => response.json())
      .then((result) => {
        patientAllergiesHandler();
      })
      .catch((error) => console.error("error", error));
  };

