  const durationTimeListHandler = () => {
    var timeArray = [];
    const ranges = [];
    const date = new Date();
    const format = {
      hour: "numeric",
      minute: "numeric",
    };

    for (let minutes = 0; minutes < 24 * 60; minutes = minutes + 30) {
      date.setHours(0);
      date.setMinutes(minutes);
      const minutesObject = {
        minutesValue: minutes,
        dateRange: date.toLocaleTimeString("ru", format),
      };
      ranges.push(minutesObject);
    }

    for (var i = 0; i < ranges.length; i++) {
      const timeObject = {
        key: i,
        time: ranges[i].dateRange,
        minutesValue: ranges[i].minutesValue,
      };
      timeArray.push(timeObject);
    }

    for (var k = 0; k < timeArray.length; k++) {
      var time = timeArray[k].time;
      if (time === "00:00") {
        timeArray.splice(k, 1);
        setDurationTimeArray(timeArray);
      }
    }
  };

