  const saveDayToDayNotes = (isTab = false) => {
    var dataList = [...DAYTODAYDATALIST];
    for (const i in dataList) {
      var ID = dataList[i].id;
    }
    if (!ID) {
      ID = 0;
    }
    const elementId = isTab ? "dayToDayNoteTextTab" : "dayToDayNoteText";
    var dayToDayNoteTxt = document.getElementById(elementId).value;
    const currentDateTime = new Date();
    const noteDateTime = `${currentDateTime.getFullYear()}-${String(currentDateTime.getMonth() + 1).padStart(2, "0")}-${String(currentDateTime.getDate()).padStart(2, "0")} ${String(currentDateTime.getHours()).padStart(2, "0")}:${String(currentDateTime.getMinutes()).padStart(2, "0")}:${String(currentDateTime.getSeconds()).padStart(2, "0")}`;

    var dayDifference = DAYSDIFFRENCE;
    if (!dayDifference || dayDifference === "" || dayDifference === 0) {
      const admissionDateStr = DAYTODAYNOTESDATA?.admissiondate;
      if (admissionDateStr) {
        const dateStr = admissionDateStr.split(" ")[0];
        const dateParts = dateStr.split("-");
        if (dateParts.length === 3) {
          const admissionDateObj = new Date(dateParts[2], dateParts[1] - 1, dateParts[0]);
          const currentDate = new Date();
          const difference = currentDate.getTime() - admissionDateObj.getTime();
          dayDifference = Math.ceil(difference / (1000 * 60 * 60 * 24));
        }
      }
      if (!dayDifference) {
        dayDifference = 0;
      }
    }

    var userID = localStorage.getItem("UserId");
    var branchID = localStorage.getItem("branch_id");
    var clinicid = localStorage.getItem("ClinicId");

    var myHeaders = apiHeaders(0);

    fetch(SAVENURSEDAYTODAYNOTES, {
      method: "POST",
      headers: myHeaders,
      body: JSON.stringify({
        admissiondate: DAYTODAYNOTESDATA.admissiondate,
        ipdid: DAYTODAYNOTESDATA.admissionid,
        notes: dayToDayNoteTxt,
        day: dayDifference,
        id: 0,
        createdByUserId: userID,
        status: 1,
      }),
    })
      .then((response) => {
        if (response.ok) return response.json();
        throw new Error(
          "Something Went Wrong While Posting Data " +
          response.status +
          " Error Code",
        );
      })
      .then((data) => {
        document.getElementById(elementId).value = "";
        if (data.id || data.status_code === 200 || data.message) {
          const optimisticNote = {
            id: data?.id || Date.now(),
            ipdid: DAYTODAYNOTESDATA.admissionid,
            day: DAYSDIFFRENCE,
            notes: dayToDayNoteTxt,
            patientid: 0,
            date: data?.date || noteDateTime,
            isindish: 0,
            createdByUserId: userID,
            admissiondate: DAYTODAYNOTESDATA.admissiondate,
            status: true,
          };

          const nextNotes = [optimisticNote, ...DAYTODAYNOTESLIST];
          syncDayToDayNotesToState(DAYTODAYNOTESDATA.admissionid, nextNotes);
          swal({
            text: "Day to day notes saved successfully...!",
            timer: 2000,
            icon: "success",
            buttons: false,
          });
          setTimeout(() => {
            getUpdatedFetchDayToDayNotesData();
          }, 2500);
        }
      })
      .catch((error) => {
        console.error(error.message);
      });
  };

