  const addNursingPlanHandler = () => {
    var patientData = JSON.parse(sessionStorage.getItem("PatientDataArray"));
    var patientId;
    var practitionerID;
    var addmissionID;
    var conditionID;
    for (const i in patientData) {
      patientId = patientData[i].clientid;
      if (!patientId) {
        patientId = patientData[i].patientid;
        if (!patientId) {
          patientId = patientData[i].patient_id;
        }
      }
      practitionerID = patientData[i].practitionerid;
      addmissionID = patientData[i].admissionid;
      conditionID = patientData[i].conditionid;
    }
    if (!NURSINGCATEGORYID) {
      swal({
        text: "Please Select Category...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    if (!NURSINGTASKID) {
      swal({
        text: "Please Select Task...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    if (!NURSINGFREQUENCYID) {
      swal({
        text: "Please Select Frequency...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var duration = NURSINGCAREDURATION;

    if (!duration) {
      swal({
        text: "Please Enter Duration...!",
        timer: 2000,
        icon: "error",
        buttons: false,
      });
      return;
    }
    var today = new Date();
    var date = new Date(today.getFullYear(), today.getMonth(), today.getDate());
    var dd = String(date.getDate()).padStart(2, "0");
    var mm = String(date.getMonth() + 1).padStart(2, "0");
    var yyyy = date.getFullYear();
    date = yyyy + "-" + mm + "-" + dd;
    var hours = today.getHours();
    var minutes = today.getMinutes();
    var seconds = today.getSeconds();
    var time = hours + ":" + minutes + ":" + seconds;
    var dateTime = date + " " + time;

    const nursingObject = {
      category: NURSINGCATEGORYNAME,
      taskname: NURSINGTASKNAME,
      frequency: NURSINGFREQUENCY,
      days: Number.parseInt(duration),
      categoryid: NURSINGCATEGORYID,
      patientid: patientId,
      practitionerid: practitionerID,
      ipdid: addmissionID,
      datetime: dateTime,
      conditionid: Number.parseInt(conditionID),
    };
    var nursingList = [...NURSINGLIST, nursingObject];
    setNursingList(nursingList);
  };

