  const getHoursMinutes = () => {
    var currentDay = new Date();
    var currentHrs = ("0" + currentDay.getHours()).substr(-2).toString();
    var currentMinutes = ("0" + currentDay.getMinutes()).substr(-2).toString();
    const tempHrsArray = Array.from(Array(25), (_, i) => i);
    const hrsArray = [];
    for (const i in tempHrsArray) {
      tempHrsArray[i] = ("0" + tempHrsArray[i]).substr(-2).toString();
      const hrsObject = {
        key: Number(i),
        hrs: tempHrsArray[i].toString(),
      };
      hrsArray.push(hrsObject);
    }
    for (const k in hrsArray) {
      if (hrsArray[k].hrs === currentHrs) {
        setHrsName(hrsArray[k].hrs);
        setHrsNameId(hrsArray[k].key);
      }
    }
    const tempMinutesArray = Array.from(Array(61), (_, i) => i);
    const minutesArray = [];
    for (const i in tempMinutesArray) {
      tempMinutesArray[i] = ("0" + tempMinutesArray[i]).substr(-2).toString();
      const minutesObject = {
        key: Number(i),
        minutes: tempMinutesArray[i].toString(),
      };
      minutesArray.push(minutesObject);
    }
    for (const k in minutesArray) {
      if (minutesArray[k].minutes === currentMinutes) {
        setMinutesName(minutesArray[k].minutes);
        setMinutesNameId(minutesArray[k].key);
      }
    }
    setMinutesArray(minutesArray);
    setHrsArray(hrsArray);
    setPatientInfoLoading(false);
  };
