  const fetchDrugInteractionData = async () => {
    try {
      var gender = patientGender;
      if (gender === "Male") {
        gender = "M";
      } else {
        gender = "F";
      }
      if (pregnancyMonth > 9) {
        swal({
          text: "Enter valid pregnancy month...!",
          timer: 2000,
          icon: "success",
          buttons: false,
        });
      }

      // const mimsIds = products.map((item) => item.mimsId);
      // setMimsIdArr(mimsIds);

      const now = new Date();

      // 1. Get active medicines (not expired)
      const activeMedicines = existMedicines.filter((item) => {
        if (!item.lastmodified || !item.days) return false;

        const modifiedDate = new Date(item.lastmodified);
        const expiryDate = new Date(modifiedDate);
        expiryDate.setDate(modifiedDate.getDate() + parseInt(item.days, 10));

        // Set expiry to end of day
        expiryDate.setHours(23, 59, 59, 999);

        return now <= expiryDate;
      });

      const activeMimsIds = activeMedicines
        .map((item) => item.mimsId)
        .filter((id) => id && id.trim() !== "");

      const newMimsIds = products
        .map((p) => p.mimsId)
        .filter((id) => id && id.trim() !== "");

      const combinedMimsIds = [...new Set([...activeMimsIds, ...newMimsIds])];
      setMimsIdArr(combinedMimsIds);

      const matchIcdCodes = healthIcdCodeArr
        .filter((item) => exitIcdCodes.some((a) => a.id === item.id))
        .map((item) => item.icdCode);

      const combineIcdCodes = [
        ...new Set([...matchIcdCodes, ...healthIcdCodeName]),
      ];

      const matchedAllergyIds = allergiesArray
        .filter((item) => existAllergies.some((sel) => sel.id === item.id))
        .map((item) => item.allergyId);

      const combineAllergyIds = [
        ...(matchedAllergyIds || []),
        ...(Array.isArray(allergyIds) ? allergyIds : []),
      ];

      const headers = apiHeaders(0);
      const response = await fetch(MIMSDRUGINTERACTION, {
        method: "POST",
        headers: {
          ...headers,
          "Content-Type": "application/json",
          Accept: "text/html",
        },
        body: JSON.stringify({
          drugGuids: combinedMimsIds,
          allergyGuids: combineAllergyIds,
          icd10Codes: combineIcdCodes,
          gender: gender,
          ageYear: patientAge,
          pregnancyWeek:
            gender === "M"
              ? 0
              : isPregnancyCheck === false
                ? 0
                : pregnancyMonth || existPregnancyWeek,
          nursing:
            isNursingCheck || existingNursingCheck === "1" ? true : false,
        }),
      });

      const htmlText = await response.text();

      const blob = new Blob([htmlText], { type: "text/html" });
      const url = URL.createObjectURL(blob);
      setDrugInteractiions(url);
    } catch (error) {
      console.error(error.message);
    }
  };

