  const repeatPrescriptionsHandler = (value) => {
    if (value) {
      if (!value.id) {
        var blankArray = [];
        setProducts(blankArray);
        localStorage.setItem("addProductList", JSON.stringify(blankArray));
        return;
      }

      var userID = localStorage.getItem("UserId");
      var branchID = localStorage.getItem("branch_id");
      var clinicid = localStorage.getItem("ClinicId");

      var myHeaders = apiHeaders(0);

      var requestOptions = {
        method: "GET",
        headers: myHeaders,
        redirect: "follow",
      };
      fetch(REPEATPRESCRIPTIONDATA + value.id, requestOptions)
        .then((response) => response.json())
        .then((result) => {
          var getData = result;
          for (var i = 0; i < getData.length; i++) {
            getData[i].addMedicineName = getData[i].drug;
            getData[i].viewMedicineName = getData[i].drug;
            let getFrequency = getData[i].dose;
            let getTiming = 0;
            var doseArray = getFrequency.split("-");
            for (var k = 0; k < doseArray.length; k++) {
              var doseValue = parseInt(doseArray[k]);
              getTiming += doseValue;
              if (doseValue == "NaN") {
                continue;
              }
              if (doseArray[k] == "0") {
                continue;
              }
              if (doseArray[k] == "1/2") {
                continue;
              } else {
                continue;
              }
            }
            getData[i].timing = getTiming;
          }
          getData.forEach((item, index) => {
            item.orderSequence = index + 1;
          });
          setProducts(getData);
          localStorage.setItem("addProductList", JSON.stringify(getData));
        })
        .catch((error) => console.error("error", error));
    }
  };

