  const setStrengthValue = () => {
    var getStrength = document.getElementById("strength").value;
    var calDose = document.getElementById("medicineDose").value;
    var weight = document.getElementById("Weight").value;
    var dosage = 0;

    if (
      getStrength === null ||
      getStrength === undefined ||
      getStrength === ""
    ) {
      getStrength = 0;
    }
    if (calDose === null || calDose === undefined || calDose === "") {
      calDose = 0;
    }
    var checkWeight = parseInt(weight);
    var checkCalDose = parseInt(calDose);
    var checkGetStrength = parseInt(getStrength);

    if (weight === null || weight === undefined || weight === "") {
      weight = 0;
    }
    if (getStrength == 0 || calDose == 0 || weight == 0) {
      dosage = 0;
    } else {
      var dosage = (checkWeight * checkCalDose) / checkGetStrength;
      if (dosage == "NaN" || dosage == "Infinity") {
        dosage = 0;
      }
    }
    document.getElementById("dosage").value = dosage.toFixed(2);
  };

