  const calculatePriscQty = () => {
    if (ISWBD !== 1) {
      var priscfrequency = document.getElementById("frequency").value;
      var priscDays = document.getElementById("days").value;
      if (priscfrequency == "0") {
        document.getElementById("Qty").value = "0";
      } else if (!priscDays) {
        document.getElementById("Qty").value = "0";
      } else {
        var str = priscfrequency.split("-");
        var priscQty = 0;
        for (var i = 0; i < str.length; i++) {
          var test = parseInt(str[i]);
          if (test == "NaN") {
            continue;
          }
          if (str[i] == "0") {
            continue;
          }
          if (str[i] == "1/2") {
            continue;
          }
          priscQty = priscQty + parseInt(str[i]) * parseInt(priscDays);
        }
        document.getElementById("Qty").value = priscQty;
      }
    }
  };

